CREATE TABLE "c_InventoryItem" ("id" BIGINT NOT NULL, "a_InventoryItem_quantity" BIGINT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Invoice" ("id" BIGINT NOT NULL, "a_Invoice_invoice_no" TEXT NOT NULL, "a_Invoice_amount" NUMERIC NOT NULL, "r_SalesOrderInvoices_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_SalesOrderInvoices_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_SalesOrderInvoices_source_id" IS NOT NULL));
CREATE TABLE "c_Party" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Customer_customer_no" TEXT, "a_Employee_employee_no" TEXT, "a_Party_name" TEXT, "a_Vendor_vendor_no" TEXT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Customer','Employee','Party','Vendor')), CHECK ((dtype IN ('Customer')) OR "a_Customer_customer_no" IS NULL), CHECK (NOT (dtype IN ('Customer')) OR "a_Customer_customer_no" IS NOT NULL), CHECK ((dtype IN ('Employee')) OR "a_Employee_employee_no" IS NULL), CHECK (NOT (dtype IN ('Employee')) OR "a_Employee_employee_no" IS NOT NULL), CHECK ((dtype IN ('Customer','Employee','Party','Vendor')) OR "a_Party_name" IS NULL), CHECK (NOT (dtype IN ('Customer','Employee','Party','Vendor')) OR "a_Party_name" IS NOT NULL), CHECK ((dtype IN ('Vendor')) OR "a_Vendor_vendor_no" IS NULL), CHECK (NOT (dtype IN ('Vendor')) OR "a_Vendor_vendor_no" IS NOT NULL));
CREATE TABLE "c_Payment" ("id" BIGINT NOT NULL, "a_Payment_amount" NUMERIC NOT NULL, "a_Payment_paid_at" TIMESTAMP NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Product" ("id" BIGINT NOT NULL, "a_Product_sku" TEXT NOT NULL, "a_Product_cost" NUMERIC NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_PurchaseOrder" ("id" BIGINT NOT NULL, "a_PurchaseOrder_po_no" TEXT NOT NULL, "a_PurchaseOrder_total" NUMERIC NOT NULL, "r_VendorPurchaseOrders_source_id" BIGINT, "r_VendorPurchaseOrders_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_VendorPurchaseOrders_source_dtype" IS NULL OR "r_VendorPurchaseOrders_source_dtype" IN ('Vendor')), CHECK ((TRUE) OR "r_VendorPurchaseOrders_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_VendorPurchaseOrders_source_id" IS NOT NULL));
CREATE TABLE "c_SalesOrder" ("id" BIGINT NOT NULL, "a_SalesOrder_so_no" TEXT NOT NULL, "a_SalesOrder_total" NUMERIC NOT NULL, "r_CustomerSalesOrders_source_id" BIGINT, "r_CustomerSalesOrders_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_CustomerSalesOrders_source_dtype" IS NULL OR "r_CustomerSalesOrders_source_dtype" IN ('Customer')), CHECK ((TRUE) OR "r_CustomerSalesOrders_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_CustomerSalesOrders_source_id" IS NOT NULL));
CREATE TABLE "c_Shipment" ("id" BIGINT NOT NULL, "a_Shipment_tracking_no" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Warehouse" ("id" BIGINT NOT NULL, "a_Warehouse_code" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "l_InvoicePayments" ("r_InvoicePayments_source_id" BIGINT NOT NULL, "r_InvoicePayments_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_InvoicePayments_source_id", "r_InvoicePayments_target_id"), UNIQUE ("r_InvoicePayments_target_id"));
CREATE TABLE "l_ProductInventory" ("r_ProductInventory_source_id" BIGINT NOT NULL, "r_ProductInventory_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_ProductInventory_source_id", "r_ProductInventory_target_id"), UNIQUE ("r_ProductInventory_target_id"));
CREATE TABLE "l_PurchaseOrderProducts" ("r_PurchaseOrderProducts_source_id" BIGINT NOT NULL, "r_PurchaseOrderProducts_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_PurchaseOrderProducts_source_id", "r_PurchaseOrderProducts_target_id"));
CREATE TABLE "l_SalesOrderProducts" ("r_SalesOrderProducts_source_id" BIGINT NOT NULL, "r_SalesOrderProducts_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_SalesOrderProducts_source_id", "r_SalesOrderProducts_target_id"));
CREATE TABLE "l_SalesOrderShipments" ("r_SalesOrderShipments_source_id" BIGINT NOT NULL, "r_SalesOrderShipments_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_SalesOrderShipments_source_id", "r_SalesOrderShipments_target_id"), UNIQUE ("r_SalesOrderShipments_target_id"));
CREATE TABLE "l_WarehouseInventory" ("r_WarehouseInventory_source_id" BIGINT NOT NULL, "r_WarehouseInventory_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_WarehouseInventory_source_id", "r_WarehouseInventory_target_id"), UNIQUE ("r_WarehouseInventory_target_id"));
