ALTER TABLE "c_PurchaseOrder" ADD CONSTRAINT "fk_c_PurchaseOrder_0" FOREIGN KEY ("r_VendorPurchaseOrders_source_id", "r_VendorPurchaseOrders_source_dtype") REFERENCES "c_Party" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
