ALTER TABLE "l_InvoicePayments" ADD CONSTRAINT "fk_l_InvoicePayments_1" FOREIGN KEY ("r_InvoicePayments_target_id") REFERENCES "c_Payment" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProductInventory" ADD CONSTRAINT "fk_l_ProductInventory_0" FOREIGN KEY ("r_ProductInventory_source_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProductInventory" ADD CONSTRAINT "fk_l_ProductInventory_1" FOREIGN KEY ("r_ProductInventory_target_id") REFERENCES "c_InventoryItem" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PurchaseOrderProducts" ADD CONSTRAINT "fk_l_PurchaseOrderProducts_0" FOREIGN KEY ("r_PurchaseOrderProducts_source_id") REFERENCES "c_PurchaseOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PurchaseOrderProducts" ADD CONSTRAINT "fk_l_PurchaseOrderProducts_1" FOREIGN KEY ("r_PurchaseOrderProducts_target_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SalesOrderProducts" ADD CONSTRAINT "fk_l_SalesOrderProducts_0" FOREIGN KEY ("r_SalesOrderProducts_source_id") REFERENCES "c_SalesOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SalesOrderProducts" ADD CONSTRAINT "fk_l_SalesOrderProducts_1" FOREIGN KEY ("r_SalesOrderProducts_target_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SalesOrderShipments" ADD CONSTRAINT "fk_l_SalesOrderShipments_0" FOREIGN KEY ("r_SalesOrderShipments_source_id") REFERENCES "c_SalesOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SalesOrderShipments" ADD CONSTRAINT "fk_l_SalesOrderShipments_1" FOREIGN KEY ("r_SalesOrderShipments_target_id") REFERENCES "c_Shipment" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_WarehouseInventory" ADD CONSTRAINT "fk_l_WarehouseInventory_0" FOREIGN KEY ("r_WarehouseInventory_source_id") REFERENCES "c_Warehouse" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_WarehouseInventory" ADD CONSTRAINT "fk_l_WarehouseInventory_1" FOREIGN KEY ("r_WarehouseInventory_target_id") REFERENCES "c_InventoryItem" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_InvoicePayments"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Payment" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_InvoicePayments" l WHERE l."r_InvoicePayments_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: InvoicePayments'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_InvoicePayments_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Payment" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_InvoicePayments"();
CREATE CONSTRAINT TRIGGER "ct_InvoicePayments_link" AFTER INSERT OR UPDATE OR DELETE ON "l_InvoicePayments" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_InvoicePayments"();
CREATE FUNCTION "require_ProductInventory"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_InventoryItem" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_ProductInventory" l WHERE l."r_ProductInventory_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: ProductInventory'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_ProductInventory_target" AFTER INSERT OR UPDATE OR DELETE ON "c_InventoryItem" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_ProductInventory"();
CREATE CONSTRAINT TRIGGER "ct_ProductInventory_link" AFTER INSERT OR UPDATE OR DELETE ON "l_ProductInventory" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_ProductInventory"();
CREATE FUNCTION "require_SalesOrderShipments"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Shipment" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_SalesOrderShipments" l WHERE l."r_SalesOrderShipments_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: SalesOrderShipments'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_SalesOrderShipments_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Shipment" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_SalesOrderShipments"();
CREATE CONSTRAINT TRIGGER "ct_SalesOrderShipments_link" AFTER INSERT OR UPDATE OR DELETE ON "l_SalesOrderShipments" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_SalesOrderShipments"();
CREATE FUNCTION "require_WarehouseInventory"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_InventoryItem" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_WarehouseInventory" l WHERE l."r_WarehouseInventory_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: WarehouseInventory'; END IF; RETURN NULL; END; $ymap$;
